from collections import deque

def find_connected_components(grid, target_value, start_pos):
    """Find all positions connected to start_pos with same value"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    component = []

    queue = deque([start_pos])
    visited.add(start_pos)

    while queue:
        r, c = queue.popleft()
        component.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == target_value:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return component

